input.command:
import random
random.seed(0)
sample=random.sample(hits, 25)
classes={}
names={}
edge_exact=0
for pos,strand in sample:
    d=ucsc(f"getData/track?genome=hg38;track=rmsk;chrom=chr21;start={pos-5};end={pos+25}")
    items=d.get("rmsk",[])
    alus=[i for i in items if i["repFamily"]=="Alu"]
    for i in items:
        classes[i["repFamily"]]=classes.get(i["repFamily"],0)+1
    for a in alus:
        names[a["repName"]]=names.get(a["repName"],0)+1
        if (a["strand"]=="+" and abs(a["genoStart"]-pos)<=5) or (a["strand"]=="-" and abs(a["genoEnd"]-(pos+20))<=5):
            edge_exact+=1
print("sampled sites:", len(sample))
print("repeat families overlapping sites:", classes)
print("sites whose Alu edge coincides with the match (within 5bp):", edge_exact, "/", len(sample))
print("Alu subfamilies seen:", names)

